class Wan:
    def __init__(self, mingzi):
        self.mingzi = mingzi

    def __enter__(self):
        print(self.mingzi + "进门")
        return self

    def __exit__(self, exc_type, exc_value, tb):
        print(self.mingzi + "出门")

with Wan("一号") as a, Wan("二号") as b:
    print("干活")

class Shouhuo:
    def ____(self):
        print("进门：开灯")
        return "猫粮碗"

    def ____(self, exc_type, exc_value, tb):
        print("出门：关灯")

with Shouhuo() as wan:
    print("拿到：", wan)
